import React from 'react';
import {Alert, Button, Dialog, DialogActions, DialogContent, DialogTitle} from '@mui/material';
import {Link} from 'react-router-dom';
import QueryError from '../shared/QueryError';
import {decimalMoney as money, useProcurementSkuQuery} from './procurementApi';
import {pricingStatuses} from './receiptPricingApi';

export default function ProcurementSkuDetail({id, close, openPurchase}: {id: number; close: () => void; openPurchase: (id: string) => void}) {
    const query = useProcurementSkuQuery(id, {pollingInterval: 10000});
    const data = query.data; const summary = data?.row.summary;
    return <Dialog open onClose={close} fullWidth maxWidth="lg">
        <DialogTitle>{data?.row.sku.name || 'История SKU'}</DialogTitle>
        <DialogContent>
            {query.isError ? <QueryError error={query.error} onRetry={query.refetch}/> : !data ? <p>Загрузка истории SKU…</p> : <>
                <p>SKU #{data.row.sku.id} · GTIN: {data.row.sku.gtin || 'ещё не присвоен'} · {data.row.sku.baseUnit || 'ед.'}</p>
                <Alert severity="info">В основной строке показано последнее фактическое поступление по дате приёмки. До первого поступления доступна справочная цена инвойса. Партии сохраняются отдельно.</Alert>
                <p>{summary?.source}</p>
                {summary?.calculatedAt && <p>Расчёт: {new Date(summary.calculatedAt).toLocaleString('ru-RU')}</p>}
                <p>Отпускная цена без НДС = себестоимость × (1 + наценка / 100). Действующая цена сохраняется до утверждения новой.</p>
                <Button component={Link} to={`/costing?mode=receipts&productId=${id}`}>Расчёты, наценка и история утверждённых цен</Button>
                <h3>Инвойсы и оплаты</h3>
                <div className="cost-table-wrap"><table className="cost-table"><thead><tr><th>Инвойс / поставщик</th><th>Количество SKU</th><th>Сумма SKU</th><th>Оплата всего инвойса</th><th/></tr></thead>
                    <tbody>{data.purchases.map(p => <tr key={p.id}>
                        <td>{p.number} · {p.date}<small>{p.supplier}</small></td><td>{p.quantity} {data.row.sku.baseUnit}</td>
                        <td>{money(p.amountFx)} {p.currency}</td><td>{money(p.paidFx)} / {money(p.invoiceTotalFx)} {p.currency}<small>{p.paymentStatus}</small></td>
                        <td><Button onClick={() => openPurchase(p.id)}>Оплаты, курсы и расходы</Button></td>
                    </tr>)}</tbody></table></div>
                {!data.purchases.length && <p>Инвойсов пока нет. Товар уже доступен для закупки.</p>}
                <h3>Фактически принятые партии</h3>
                <div className="cost-table-wrap"><table className="cost-table"><thead><tr><th>Поступление</th><th>Принято</th><th>Закупочная цена, BYN</th><th>Себестоимость, BYN</th><th>Наценка, %</th><th>Предложенная цена без НДС, BYN</th><th>Этап</th></tr></thead>
                    <tbody>{data.receipts.map(c => <tr key={c.receiptLineId}>
                        <td>{c.purchase.sourceDocumentNumber || c.receiptId.slice(0, 8)}<small>{new Date(c.postedAt).toLocaleString('ru-RU')} · {c.supplier} · {c.warehouse}</small><small>Версия расчёта {c.version}</small></td>
                        <td>{c.acceptedQuantity} {c.purchase.baseUnit}</td>
                        <td>{money(c.managementEvidence?.cost.unitPurchaseByn ?? c.purchase.bynExRecoverableVatPerBaseUnit)}<small>{money(c.purchase.originalUnitPrice)} {c.purchase.currency}/{c.purchase.purchaseUnit}</small></td>
                        <td>{money(c.costByn)}</td><td>{money(c.markupPercent)}</td><td>{money(c.proposedPriceExVat)}</td><td>{pricingStatuses[c.status]}</td>
                    </tr>)}</tbody></table></div>
                {!data.receipts.length && <p>Фактических поступлений нет. Ожидаемая поставка не увеличивает доступный остаток.</p>}
            </>}
        </DialogContent>
        <DialogActions><Button onClick={close}>Закрыть</Button></DialogActions>
    </Dialog>;
}
