import React, {useState} from "react";
import {Button, Chip, MenuItem, Pagination, Tab, Tabs, TextField} from "@mui/material";
import {Link} from "react-router-dom";
import AddIcon from "@mui/icons-material/Add";
import {useAuth} from "../../auth/AuthContext";
import {useCostingDashboardQuery, useCostingListQuery} from "./costingApi";
import {money, statuses} from "./types";
import useDebounce from "../../hooks/useDebounce";
import QueryError from "../shared/QueryError";
import Loader from "../../ui/loader/loader";
import CostResources from "./CostResources";
import CostingMethods from "./CostingMethods";
import ReceiptPricingPage from "./ReceiptPricingPage";
import ProcurementCostingPage from "./ProcurementCostingPage";
import {useSearchParams} from "react-router-dom";
import "./costing.css";

function Registry() {
    const [query, setQuery] = useState(""); const search = useDebounce(query); const [page, setPage] = useState(1); const [status, setStatus] = useState<number | "">(""); const [kind, setKind] = useState<number | "">("");
    const {data, isLoading, isError, error, refetch} = useCostingListQuery({search, page, ...(status === "" ? {} : {status}), ...(kind === "" ? {} : {kind})});
    return <section className="cost-panel"><div className="cost-fields"><TextField size="small" label="Поиск по позиции или калькуляции" value={query} onChange={e => {setQuery(e.target.value); setPage(1);}}/><TextField select size="small" label="Статус" value={status} onChange={e => {setStatus(e.target.value === "" ? "" : Number(e.target.value)); setPage(1);}}><MenuItem value="">Все статусы</MenuItem>{statuses.map((name, i) => <MenuItem key={i} value={i}>{name}</MenuItem>)}</TextField><TextField select size="small" label="Тип расчёта" value={kind} onChange={e => {setKind(e.target.value === "" ? "" : Number(e.target.value)); setPage(1);}}><MenuItem value="">Все расчёты</MenuItem><MenuItem value={0}>Нормативный</MenuItem><MenuItem value={1}>Фактический</MenuItem></TextField></div>
        {isLoading ? <Loader/> : isError ? <QueryError error={error} onRetry={refetch}/> : !data?.items.length ? <div className="cost-empty"><strong>Калькуляций пока нет</strong><span>Создайте расчёт из реестра или из карточки товара и услуги.</span><Button component={Link} to="/costing/new" variant="outlined">Создать калькуляцию</Button></div> : <><div className="cost-table-wrap"><table className="cost-table"><thead><tr><th>Позиция / калькуляция</th><th>Версия</th><th>Статус</th><th>Производственная / ед.</th><th>Полная / ед.</th><th>Маржа</th><th>Изменена</th></tr></thead><tbody>{data.items.map(c => <tr key={c.id}><td><Link to={`/costing/${c.id}`}>{c.itemName}</Link><small>{c.name} · {c.itemType === 0 ? "Товар" : "Услуга"} · {c.kind === 0 ? "План" : "Факт"}</small></td><td>v{c.version}</td><td><Chip size="small" label={statuses[c.status]} color={c.status === 1 ? "success" : "default"}/></td><td className="number">{money(c.snapshot.result.productionUnitCost)} {c.snapshot.input.currency}</td><td className="number">{money(c.snapshot.result.fullUnitCost)} {c.snapshot.input.currency}</td><td className="number">{money(c.snapshot.result.marginPercent)}%</td><td>{new Date(c.updatedAt).toLocaleDateString("ru-RU")}</td></tr>)}</tbody></table></div><div className="cost-header" style={{marginTop: 18}}><span className="cost-note">Всего: {data.total}</span><Pagination count={Math.ceil(data.total / data.pageSize)} page={page} onChange={(_, value) => setPage(value)}/></div></>}
    </section>;
}
function Dashboard() {
    const {data, isLoading, isError, error, refetch} = useCostingDashboardQuery();
    if (isLoading) return <Loader/>; if (isError) return <QueryError error={error} onRetry={refetch}/>; if (!data) return null;
    return <><div className="cost-stats">{[["Действующих калькуляций", data.approvedCount], ["Цена ниже себестоимости", data.belowCostCount], ["Без цены продажи", data.missingSellingPriceCount]].map(([label, value]) => <div className="cost-stat" key={label}><span>{label}</span><strong>{value}</strong></div>)}</div><section className="cost-panel"><h2>Рентабельность действующих позиций</h2><p className="cost-note">Сравнение использует текущую цену карточки и утверждённую себестоимость. Для валюты, отличной от BYN, сравнение не выполняется.</p>{!data.items.length ? <div className="cost-empty">Утвердите нормативную калькуляцию, чтобы увидеть показатели.</div> : <div className="cost-table-wrap"><table className="cost-table"><thead><tr><th>Позиция</th><th>Цена каталога, BYN</th><th>Полная / ед.</th><th>Прибыль / ед.</th><th>Маржа</th></tr></thead><tbody>{data.items.map(x => <tr key={`${x.item.type}-${x.item.id}`}><td><Link to={`/costing/${x.approved!.id}`}>{x.item.name}</Link></td><td className="number">{money(x.item.sellingPrice)}</td><td className="number">{money(x.approved!.snapshot.result.fullUnitCost)} {x.approved!.snapshot.input.currency}</td><td className="number" style={{color: (x.profitPerUnit ?? 0) < 0 ? "#d65050" : undefined}}>{money(x.profitPerUnit)}</td><td className="number">{money(x.marginPercent)}%</td></tr>)}</tbody></table></div>}</section></>;
}
function Workspace() {
    const [tab, setTab] = useState(0);
    return <div className="cost-page"><header className="cost-header"><div><span className="cost-eyebrow">Финансы / калькуляции</span><h1>Себестоимость</h1><p>От норм расхода до рентабельности: прозрачные расчёты товаров и услуг, версии, ставки и план-факт.</p></div><Button component={Link} to="/costing/new" variant="contained" startIcon={<AddIcon/>}>Новая калькуляция</Button></header><Tabs value={tab} onChange={(_, v) => setTab(v)} variant="scrollable" scrollButtons="auto" aria-label="Разделы себестоимости"><Tab label="Калькуляции"/><Tab label="Ресурсы и ставки"/><Tab label="Рентабельность"/><Tab label="Методика расчёта"/></Tabs>{tab === 0 ? <Registry/> : tab === 1 ? <CostResources/> : tab === 2 ? <Dashboard/> : <CostingMethods/>}</div>;
}
export default function CostingPage() {
    const {isCompanyAdmin, isSuperAdmin} = useAuth(); const [params, setParams] = useSearchParams();
    const mode = params.get("mode") === "receipts" ? 1 : params.get("mode") === "standard" && (isCompanyAdmin || isSuperAdmin) ? 2 : 0;
    return <><Tabs sx={{px: 3, borderBottom: 1, borderColor: "divider"}} value={mode} onChange={(_, value) => setParams(p => {p.set("mode", value === 1 ? "receipts" : value === 2 ? "standard" : "catalog"); return p;})} aria-label="Виды расчёта себестоимости"><Tab label="Товары и валютные закупки"/><Tab label="По поступлениям"/>{(isCompanyAdmin || isSuperAdmin) && <Tab label="Нормативные калькуляции"/>}</Tabs>{mode === 0 ? <ProcurementCostingPage/> : mode === 1 ? <ReceiptPricingPage/> : <Workspace/>}</>;
}
