import {costingApi} from "./costingApi";
import type {ReceiptCalculation} from "./receiptPricingApi";

export type FxRate = {id: string; currency: string; effectiveDate: string; scale: number; officialRate: number; perUnit: number; source: string; retrievedAt: string; manualReason: string};
export type InvoiceLine = {id: string; productId: number; name: string; gtin: string; quantity: number; unit: string; unitPriceFx: number; baseUnit: string; unitsPerPurchaseUnit: number; baseQuantity: number; amountFx: number; vatPercent: number; weightPerBaseUnit: number; volumePerBaseUnit: number};
export type PurchasePayment = {id: string; date: string; amountFx: number; actualByn: number | null; bankRate: number | null; officialRate: FxRate | null; reference: string; voidReason: string | null; rateError: string};
export type ProcurementInvoice = {id: string; title: string; supplier: string; number: string; date: string; currency: string; lines: InvoiceLine[]; payments: PurchasePayment[]; invoiceRate: FxRate | null; rateError: string};
export type AllocationShare = {lineId: string; amount: number};
export type ProcurementExpense = {id: string; name: string; amount: number; currency: string; actualByn: number | null; date: string; document: string; includeInCost: boolean; allocation: number; receiptId: string | null; manualShares: AllocationShare[] | null; rate: FxRate | null; byn: number | null};
export type ManagementReceiptCost = {calculationId: string; receiptLineId: string; receiptId: string; invoiceLineId: string; productId: number; quantity: number; basePurchaseByn: number | null; expensesByn: number | null; totalByn: number | null; unitPurchaseByn: number | null; unitCostByn: number | null; isPreliminary: boolean; method: string; warnings: string[]};
export type ManagementVersion = {id: string; purchaseId: string; version: number; createdAt: string; createdBy: string; fingerprint: string; input: {invoice: ProcurementInvoice; expenses: ProcurementExpense[]; valuationRates: {date: string; rate: FxRate | null; error: string}[]}; result: {invoiceAmountFx: number; paidFx: number; confirmedPaymentByn: number | null; receipts: ManagementReceiptCost[]; warnings: string[]}};
export type ManagementEvidence = {versionId: string; version: number; purchaseId: string; cost: ManagementReceiptCost; input: ManagementVersion["input"]; fixedAt: string};
export type ProcurementLedger = {id: string; stamp: string; valuationDate: string | null; expenses: ProcurementExpense[]; paymentAllocations: {paymentId: string; shares: AllocationShare[]; reason: string}[]; paymentValuations: {paymentId: string; byn: number; method: string; reason: string; confirmedBy: string; confirmedAt: string}[]; adjustments: {id: string; lineId: string; byn: number; reason: string; document: string; date: string}[]; events: {at: string; actor: string; action: string; note: string}[]};
export type ProcurementView = {invoice: ProcurementInvoice; ledger: ProcurementLedger; receipts: ReceiptCalculation[]; versions: ManagementVersion[]};
export type CostingSkuSummary = {purchaseByn: number | null; costByn: number | null; markupPercent: number | null; sellingPriceByn: number | null; isPreliminary: boolean; source: string; receiptId: string | null; purchaseId: string | null; calculatedAt: string | null};
export type CostingSkuRow = {sku: {id: number; name: string; gtin: string; baseUnit: string; sellingPrice: number; hasApprovedPrice: boolean}; purchases: number; status: string; lots: ManagementReceiptCost[]; summary: CostingSkuSummary; paymentStatus: string; receiptStatus: string};
export type CostingSkuDetail = {row: CostingSkuRow; purchases: {id: string; supplier: string; number: string; date: string; currency: string; quantity: number; amountFx: number; invoiceTotalFx: number; paidFx: number; paymentStatus: string}[]; receipts: ReceiptCalculation[]};
export type CostingSkuStage = {id: number; name: string; gtin: string; baseUnit: string; status: string};
const api = costingApi.injectEndpoints({endpoints: b => ({
    procurementCatalog: b.query<{items: CostingSkuRow[]; total: number; page: number; pageSize: number}, {search?: string; page?: number}>({query: params => ({url: "procurement/catalog", params}), providesTags: ["Costing"]}),
    procurementSku: b.query<CostingSkuDetail, number>({query: id => `procurement/catalog/${id}`, providesTags: ["Costing"]}),
    procurementCatalogStages: b.query<{items: CostingSkuStage[]; total: number; page: number; pageSize: number}, {search?: string; page?: number}>({query: params => ({url: "procurement/catalog/stages", params}), providesTags: ["Costing"]}),
    procurementInvoices: b.query<ProcurementInvoice[], void>({query: () => "procurement/purchases", providesTags: ["Costing"]}),
    procurementInvoice: b.query<ProcurementView, string>({query: id => `procurement/purchases/${id}`, providesTags: ["Costing"]}),
    saveProcurementInputs: b.mutation<ProcurementLedger, {id: string; stamp: string; valuationDate: string | null; expenses: ProcurementExpense[]; paymentAllocations: ProcurementLedger["paymentAllocations"]; adjustments: ProcurementLedger["adjustments"]; reason: string}>({query: ({id, ...body}) => ({url: `procurement/purchases/${id}/inputs`, method: "PUT", body}), invalidatesTags: ["Costing"]}),
    calculateProcurement: b.mutation<ManagementVersion, string>({query: id => ({url: `procurement/purchases/${id}/calculate`, method: "POST"}), invalidatesTags: ["Costing"]}),
    linkProcurementReceipt: b.mutation<ReceiptCalculation, {id: string; calculationId: string; lineId: string; stamp: string; reason: string}>({query: ({id, ...body}) => ({url: `procurement/purchases/${id}/link-receipt`, method: "POST", body}), invalidatesTags: ["Costing"]}),
    applyManagementCost: b.mutation<ReceiptCalculation, {versionId: string; calculationId: string; stamp: string}>({query: ({versionId, ...body}) => ({url: `procurement/versions/${versionId}/apply`, method: "POST", body}), invalidatesTags: ["Costing"]}),
    confirmPaymentValuation: b.mutation<ProcurementLedger, {id: string; stamp: string; paymentId: string; byn: string; method: string; reason: string}>({query: ({id, ...body}) => ({url: `procurement/purchases/${id}/payment-valuation`, method: "POST", body}), invalidatesTags: ["Costing"]}),
    fetchCurrencyRate: b.query<FxRate, {currency: string; date: string}>({query: params => ({url: "procurement/rates", params})}),
    manualCurrencyRate: b.mutation<FxRate, {currency: string; date: string; scale: number; rate: string; reason: string}>({query: body => ({url: "procurement/rates", method: "POST", body}), invalidatesTags: ["Costing"]}),
})});
export const {useProcurementCatalogQuery, useProcurementSkuQuery, useProcurementCatalogStagesQuery, useProcurementInvoicesQuery, useProcurementInvoiceQuery, useSaveProcurementInputsMutation, useCalculateProcurementMutation, useLinkProcurementReceiptMutation, useApplyManagementCostMutation, useConfirmPaymentValuationMutation, useLazyFetchCurrencyRateQuery, useManualCurrencyRateMutation} = api;
export const decimalMoney = (value: number | null | undefined) => value == null ? "—" : value.toLocaleString("ru-RU", {minimumFractionDigits: 2, maximumFractionDigits: 8});
export const procurementError = (error: unknown) => {const e = error as {data?: {message?: string; detail?: string}; message?: string}; return e?.data?.message || e?.data?.detail || e?.message || "Не удалось выполнить действие. Обновите данные.";};
