import React, {useState} from "react";
import {Alert, Button, Dialog, DialogActions, DialogContent, DialogTitle, TextField} from "@mui/material";
import {useArchiveCostResourceMutation, useCostResourcesQuery, useSaveCostResourceMutation} from "./costingApi";
import {categories, money, Resource} from "./types";
import {NumberField, SelectField} from "./CostFields";
import {getApiErrorMessage} from "../../api/errors";
import QueryError from "../shared/QueryError";
import Loader from "../../ui/loader/loader";
const empty = {name: "", unit: "шт", currency: "BYN", category: 0, unitCost: 0, notes: "", stamp: "00000000-0000-0000-0000-000000000000"};
export default function CostResources() {
    const {data = [], isLoading, isError, error, refetch} = useCostResourcesQuery();
    const [save, saving] = useSaveCostResourceMutation(); const [archive, archiving] = useArchiveCostResourceMutation();
    const [form, setForm] = useState<typeof empty & {id?: string}>(empty); const [open, setOpen] = useState(false); const [failure, setFailure] = useState("");
    const [archived, setArchived] = useState<Resource | null>(null);
    const submit = async () => {try {await save(form).unwrap(); setOpen(false); setFailure("");} catch (e) {setFailure(getApiErrorMessage(e, "Ставка не сохранена"));}};
    const set = (key: keyof typeof empty, value: string | number) => setForm({...form, [key]: value});
    if (isLoading) return <Loader/>; if (isError) return <QueryError error={error} onRetry={refetch}/>;
    return <section className="cost-panel"><div className="cost-header"><div><h2>Справочник ресурсов и ставок</h2><p>Материалы, часовые ставки, оборудование и услуги подрядчиков. Каждая калькуляция фиксирует использованную ставку.</p></div><Button variant="contained" onClick={() => {setForm(empty); setFailure(""); setOpen(true);}}>Добавить ресурс</Button></div>
        {!data.length ? <div className="cost-empty"><strong>Добавьте первый ресурс</strong><span>Например, материал за кг, работу за час или аренду оборудования.</span></div> : <div className="cost-table-wrap"><table className="cost-table"><thead><tr><th>Ресурс</th><th>Категория</th><th>Ставка</th><th>Обновлён</th><th>Действия</th></tr></thead><tbody>{data.map(r => <tr key={r.id}><td><strong>{r.name}</strong><small>{r.notes}</small></td><td>{categories[r.category]}</td><td className="number">{money(r.unitCost, 4)} {r.currency}/{r.unit}</td><td>{new Date(r.updatedAt).toLocaleDateString("ru-RU")}</td><td><Button onClick={() => {setForm(r); setFailure(""); setOpen(true);}}>Изменить</Button><Button color="warning" onClick={() => setArchived(r)}>В архив</Button></td></tr>)}</tbody></table></div>}
        <Dialog fullWidth maxWidth="sm" open={open} onClose={() => {if (!saving.isLoading) setOpen(false);}}><DialogTitle>{form.id ? "Изменить ставку" : "Новый ресурс"}</DialogTitle><DialogContent>{failure && <Alert severity="error" sx={{mb: 2}}>{failure}</Alert>}<div className="cost-fields" style={{paddingTop: 10}}>
            <TextField size="small" label="Название" value={form.name} onChange={e => set("name", e.target.value)}/><SelectField label="Категория" value={form.category} options={categories} onChange={v => set("category", v)}/><TextField size="small" label="Единица измерения" value={form.unit} onChange={e => set("unit", e.target.value)}/><TextField size="small" label="Валюта" inputProps={{maxLength: 3}} value={form.currency} onChange={e => set("currency", e.target.value.toUpperCase())}/><NumberField label="Ставка / цена за единицу" value={form.unitCost} onChange={v => set("unitCost", v)}/><TextField size="small" multiline label="Поставщик, документ, условия НДС" value={form.notes} onChange={e => set("notes", e.target.value)}/>
        </div>{form.id && <p className="cost-note">Изменение ставки не пересчитывает сохранённые калькуляции. Условия НДС задаются в строке калькуляции.</p>}</DialogContent><DialogActions><Button disabled={saving.isLoading} onClick={() => setOpen(false)}>Отмена</Button><Button disabled={saving.isLoading} onClick={() => void submit()}>Сохранить</Button></DialogActions></Dialog>
        <Dialog open={!!archived} onClose={() => setArchived(null)}><DialogTitle>Архивировать ресурс?</DialogTitle><DialogContent>{archived?.name}. Исторические калькуляции сохранят использованную ставку.{archiving.error && <Alert severity="error">{getApiErrorMessage(archiving.error, "Ресурс не архивирован")}</Alert>}</DialogContent><DialogActions><Button disabled={archiving.isLoading} onClick={() => setArchived(null)}>Отмена</Button><Button disabled={archiving.isLoading} onClick={() => {if (archived) void archive({id: archived.id, stamp: archived.stamp}).unwrap().then(() => setArchived(null)).catch(() => undefined);}}>В архив</Button></DialogActions></Dialog>
    </section>;
}
