import React, {useState} from "react";
import {Accordion, AccordionDetails, AccordionSummary, Autocomplete, Checkbox, FormControlLabel, IconButton, MenuItem, TextField} from "@mui/material";
import DeleteOutlineIcon from "@mui/icons-material/DeleteOutline";
import ExpandMoreIcon from "@mui/icons-material/ExpandMore";
import {allocationBases, categories, CostLine, Overhead, Resource} from "./types";
import {useCostingCatalogQuery} from "./costingApi";
import useDebounce from "../../hooks/useDebounce";

export function NumberField({label, value, onChange, disabled, max}: {label: string; value: number; onChange: (value: number) => void; disabled?: boolean; max?: number}) {
    return <TextField size="small" type="number" label={label} value={value} disabled={disabled} inputProps={{min: 0, max, step: "any"}} onChange={e => {const n = Number(e.target.value); if (Number.isFinite(n)) onChange(n);}}/>;
}
export function SelectField({label, value, options, onChange, disabled}: {label: string; value: number; options: string[]; onChange: (value: number) => void; disabled?: boolean}) {
    return <TextField select size="small" label={label} value={value} disabled={disabled} onChange={e => onChange(Number(e.target.value))}>{options.map((name, i) => <MenuItem value={i} key={i}>{name}</MenuItem>)}</TextField>;
}
export function LineFields({line, index, resources, disabled, onChange, onRemove}: {line: CostLine; index: number; resources: Resource[]; disabled: boolean; onChange: (line: CostLine) => void; onRemove: () => void}) {
    const [query, setQuery] = useState(""); const search = useDebounce(query);
    const {data: components = []} = useCostingCatalogQuery(search, {skip: line.source !== 2 || disabled});
    const set = (key: keyof CostLine, value: string | number | boolean | null) => onChange({...line, [key]: value});
    return <div className="cost-line">
        <div className="cost-line-head"><strong>{index + 1}. {line.name || "Новая статья затрат"}</strong>{!disabled && <IconButton aria-label={`Удалить строку ${index + 1}`} onClick={onRemove}><DeleteOutlineIcon/></IconButton>}</div>
        <div className="cost-fields">
            <TextField size="small" label="Название статьи" value={line.name} disabled={disabled} onChange={e => set("name", e.target.value)}/>
            <SelectField label="Категория" value={line.category} options={categories} disabled={disabled || line.source === 1} onChange={category => onChange({...line, category, lossPercent: category === 0 ? line.lossPercent : 0, burdenPercent: category === 1 ? line.burdenPercent : 0})}/>
            <SelectField label="Источник ставки" value={line.source} options={["Ввести вручную", "Справочник ресурсов", "Себестоимость из каталога"]} disabled={disabled} onChange={source => onChange({...line, source, resourceId: null, componentId: null, componentType: null, sourceDescription: null})}/>
            <SelectField label="Поведение затрат" value={line.behavior} options={["Переменные", "Постоянные"]} disabled={disabled} onChange={v => set("behavior", v)}/>
            <SelectField label="Количество задано" value={line.scope} options={["На единицу выпуска", "На всю партию"]} disabled={disabled} onChange={v => set("scope", v)}/>
            <NumberField label="Количество / норма" value={line.quantity} disabled={disabled} onChange={v => set("quantity", v)}/>
            <TextField size="small" label="Единица измерения" value={line.unit} disabled={disabled || line.source === 1} onChange={e => set("unit", e.target.value)}/>
            <NumberField label="Ставка / цена ресурса" value={line.unitCost} disabled={disabled || line.source !== 0} onChange={v => set("unitCost", v)}/>
        </div>
        {line.source === 1 && <TextField select fullWidth size="small" sx={{mt: 2}} label="Ресурс" value={line.resourceId ?? ""} disabled={disabled} onChange={e => {const r = resources.find(x => x.id === e.target.value); if (r) onChange({...line, resourceId: r.id, name: line.name || r.name, category: r.category, unit: r.unit, unitCost: r.unitCost, lossPercent: r.category === 0 ? line.lossPercent : 0, burdenPercent: r.category === 1 ? line.burdenPercent : 0});}}>
            {line.resourceId && !resources.some(x => x.id === line.resourceId) && <MenuItem value={line.resourceId}>Сохранённый ресурс (недоступен)</MenuItem>}{resources.map(r => <MenuItem key={r.id} value={r.id}>{r.name} · {r.unitCost} {r.currency}/{r.unit}</MenuItem>)}
        </TextField>}
        {line.source === 2 && <Autocomplete sx={{mt: 2}} options={components} disabled={disabled} value={components.find(x => x.id === line.componentId && x.type === line.componentType) ?? (line.componentId != null ? {id: line.componentId, type: line.componentType ?? 0, name: line.sourceDescription || line.name, sellingPrice: 0} : null)}
            isOptionEqualToValue={(a, b) => a.id === b.id && a.type === b.type} getOptionLabel={x => `${x.type === 0 ? "Товар" : "Услуга"} · ${x.name}`}
            onInputChange={(_, value, reason) => {if (reason === "input") setQuery(value);}} onChange={(_, item) => onChange({...line, componentId: item?.id ?? null, componentType: item?.type ?? null, name: line.name || item?.name || "", taxPercent: 0, discountPercent: 0, burdenPercent: 0, exchangeRate: 1})}
            renderInput={params => <TextField {...params} size="small" label="Компонент с утверждённой калькуляцией"/>}/>}
        {line.sourceDescription && <p className="cost-note">Зафиксированный источник: {line.sourceDescription}</p>}
        <Accordion disableGutters elevation={0} sx={{mt: 2, background: "transparent", "&:before": {display: "none"}}}>
            <AccordionSummary expandIcon={<ExpandMoreIcon/>}>НДС, скидка, потери и начисления</AccordionSummary>
            <AccordionDetails><div className="cost-fields">
                <NumberField label="Курс к валюте расчёта" value={line.exchangeRate} disabled={disabled || line.source === 2} onChange={v => set("exchangeRate", v)}/>
                <NumberField label="Скидка, %" value={line.discountPercent} disabled={disabled || line.source === 2} max={100} onChange={v => set("discountPercent", v)}/>
                <NumberField label="НДС ресурса, %" value={line.taxPercent} disabled={disabled || line.source === 2} max={100} onChange={v => set("taxPercent", v)}/>
                <NumberField label="Возмещаемая доля НДС, %" value={line.recoverableTaxPercent} disabled={disabled || line.source === 2} max={100} onChange={v => set("recoverableTaxPercent", v)}/>
                {line.category === 0 && <NumberField label="Нормативные потери материала, %" value={line.lossPercent} disabled={disabled} max={99.99} onChange={v => set("lossPercent", v)}/>}
                {line.category === 1 && <NumberField label="Начисления на оплату труда, %" value={line.burdenPercent} disabled={disabled || line.source === 2} onChange={v => set("burdenPercent", v)}/>}
                <FormControlLabel control={<Checkbox checked={line.priceIncludesTax} disabled={disabled || line.source === 2} onChange={e => set("priceIncludesTax", e.target.checked)}/>} label="Ставка включает НДС"/>
            </div><p className="cost-note">Потери материала увеличивают расход по формуле «норма / (1 − потери)». Если труд задан в часах, задайте часы распределения отдельно в параметрах выпуска.</p></AccordionDetails>
        </Accordion>
    </div>;
}
export function OverheadFields({rule, index, disabled, onChange, onRemove}: {rule: Overhead; index: number; disabled: boolean; onChange: (rule: Overhead) => void; onRemove: () => void}) {
    const set = (key: keyof Overhead, value: string | number) => onChange({...rule, [key]: value});
    return <div className="cost-line"><div className="cost-line-head"><strong>{index + 1}. {rule.name || "Накладные расходы"}</strong>{!disabled && <IconButton aria-label={`Удалить правило ${index + 1}`} onClick={onRemove}><DeleteOutlineIcon/></IconButton>}</div>
        <div className="cost-fields">
            <TextField size="small" label="Название расходов" value={rule.name} disabled={disabled} onChange={e => set("name", e.target.value)}/>
            <TextField select size="small" label="Категория расходов" value={rule.category} disabled={disabled} onChange={e => set("category", Number(e.target.value))}>{[5, 6, 7].map(i => <MenuItem key={i} value={i}>{categories[i]}</MenuItem>)}</TextField>
            <SelectField label="Поведение" value={rule.behavior} options={["Переменные", "Постоянные"]} disabled={disabled} onChange={v => set("behavior", v)}/>
            <SelectField label="Способ распределения" value={rule.method} options={["Ставка на драйвер", "Процент от затрат", "Пул за период / мощность"]} disabled={disabled} onChange={method => onChange({...rule, method, base: method === 1 ? 5 : 0})}/>
            <TextField select size="small" label="База распределения" value={rule.base} disabled={disabled} onChange={e => set("base", Number(e.target.value))}>{allocationBases.map((name, i) => ((rule.method === 1) === (i >= 3 && i <= 5)) && <MenuItem key={i} value={i}>{name}</MenuItem>)}</TextField>
            <NumberField label={rule.method === 1 ? "Процент" : rule.method === 2 ? "Общая сумма пула за период" : "Ставка на единицу драйвера"} value={rule.amount} disabled={disabled} onChange={v => set("amount", v)}/>
            {rule.base === 6 && <NumberField label="Операции этой калькуляции" value={rule.driverQuantity} disabled={disabled} onChange={v => set("driverQuantity", v)}/>}
            {rule.method === 2 && <NumberField label="Общая фактическая база пула" value={rule.actualCapacity} disabled={disabled} onChange={v => set("actualCapacity", v)}/>}
            {rule.method === 2 && rule.category === 5 && rule.behavior === 1 && <NumberField label="Нормальная мощность пула" value={rule.normalCapacity} disabled={disabled} onChange={v => set("normalCapacity", v)}/>}
        </div><p className="cost-note">База и мощность задаются в одинаковых единицах. Для постоянного производственного пула используется максимум нормальной и фактической мощности. Каждый пул учитывайте один раз.</p>
    </div>;
}
