import React, {useEffect, useState} from "react";
import {Alert, Button, Checkbox, Chip, Dialog, DialogActions, DialogContent, DialogTitle, FormControlLabel, MenuItem, Pagination, Tab, Tabs, TextField} from "@mui/material";
import {Link, useSearchParams} from "react-router-dom";
import QueryError from "../shared/QueryError";
import useDebounce from "../../hooks/useDebounce";
import {newRequestId} from "../warehouse/receiptDraft";
import {PricingAccess, useReceiptPricingPolicyQuery, useReceiptPricingQuery} from "./receiptPricingApi";
import ReceiptPricingPage from "./ReceiptPricingPage";
import ProcurementSkuDetail from "./ProcurementSkuDetail";
import {ProcurementExpense, ProcurementView, decimalMoney as money, procurementError, useApplyManagementCostMutation, useCalculateProcurementMutation, useConfirmPaymentValuationMutation, useLazyFetchCurrencyRateQuery, useLinkProcurementReceiptMutation, useManualCurrencyRateMutation, useProcurementCatalogQuery, useProcurementInvoiceQuery, useProcurementInvoicesQuery, useSaveProcurementInputsMutation} from "./procurementApi";
import {useProcurementCatalogStagesQuery} from "./procurementApi";

function RatePanel({canOverride}: {canOverride: boolean}) {
    const [currency, setCurrency] = useState("RUB"); const [date, setDate] = useState(new Date().toISOString().slice(0, 10)); const [scale, setScale] = useState("100"); const [rate, setRate] = useState(""); const [reason, setReason] = useState(""); const [failure, setFailure] = useState("");
    const [fetchRate, lookup] = useLazyFetchCurrencyRateQuery(); const [manual, manualState] = useManualCurrencyRateMutation();
    return <details className="cost-panel"><summary>Курсы НБРБ на дату события и ручное подтверждение</summary><p className="cost-note">Официальный курс сохраняется вместе с масштабом. Курс за 100 RUB нельзя применять как курс за 1 RUB. Утверждённые расчёты сохраняют свой снимок.</p>
        {failure && <Alert severity="error">{failure}</Alert>}<div className="cost-fields"><TextField label="Валюта курса" value={currency} onChange={e => setCurrency(e.target.value.toUpperCase())}/><TextField label="Дата курса" type="date" value={date} InputLabelProps={{shrink: true}} onChange={e => setDate(e.target.value)}/><Button disabled={lookup.isFetching} onClick={async () => {setFailure(""); try {await fetchRate({currency, date}, false).unwrap();} catch (e) {setFailure(procurementError(e));}}}>Получить / прочитать сохранённый курс</Button></div>
        {lookup.data && <Alert sx={{my: 2}} severity="info">{lookup.data.scale} {lookup.data.currency} = {money(lookup.data.officialRate)} BYN; за 1 — {money(lookup.data.perUnit)} BYN. Дата: {lookup.data.effectiveDate}. Источник: {lookup.data.source}{lookup.data.manualReason && `; основание: ${lookup.data.manualReason}`}</Alert>}
        {canOverride && <div className="cost-fields"><TextField label="Масштаб ручного курса" value={scale} onChange={e => setScale(e.target.value)}/><TextField label="BYN за указанный масштаб" value={rate} onChange={e => setRate(e.target.value)}/><TextField label="Основание ручного курса" value={reason} onChange={e => setReason(e.target.value)}/><Button disabled={manualState.isLoading || !reason.trim() || !rate} onClick={async () => {try {await manual({currency, date, scale: Number(scale), rate: rate.replace(",", "."), reason}).unwrap(); setFailure(""); await fetchRate({currency, date}, false).unwrap();} catch (e) {setFailure(procurementError(e));}}}>Зафиксировать ручной курс</Button></div>}
    </details>;
}

function ExpenseEditor({view, close}: {view: ProcurementView; close: () => void}) {
    const [stamp] = useState(view.ledger.stamp);
    const [expenses, setExpenses] = useState(view.ledger.expenses); const [valuationDate, setValuationDate] = useState(view.ledger.valuationDate || "");
    const [allocations, setAllocations] = useState(view.ledger.paymentAllocations); const [adjustments, setAdjustments] = useState(view.ledger.adjustments); const [reason, setReason] = useState(""); const [failure, setFailure] = useState(""); const [save, state] = useSaveProcurementInputsMutation();
    const update = (id: string, patch: Partial<ProcurementExpense>) => setExpenses(rows => rows.map(r => r.id === id ? {...r, ...patch} : r));
    const invoice = view.invoice; const receiptIds = Array.from(new Set(view.receipts.map(r => r.receiptId)));
    return <Dialog open onClose={close} maxWidth="lg" fullWidth><DialogTitle>Расходы, распределение и корректировки</DialogTitle><DialogContent>{failure && <Alert severity="error">{failure}</Alert>}
        <Alert severity="info" sx={{mb: 2}}>Расход вводится один раз. Расход всей закупки распределяется между частичными поступлениями пропорционально их доле. Для расхода конкретной партии выберите поступление.</Alert>
        <TextField type="date" label="Дата оценки неоплаченного остатка" InputLabelProps={{shrink: true}} value={valuationDate} onChange={e => setValuationDate(e.target.value)} helperText="Пусто — дата каждого фактического прихода"/>
        {expenses.map(e => <section className="cost-line" key={e.id}><div className="cost-fields"><TextField label="Статья расхода" value={e.name} onChange={v => update(e.id, {name: v.target.value})}/><TextField label="Сумма расхода" type="number" value={e.amount} onChange={v => update(e.id, {amount: Number(v.target.value)})}/><TextField label="Валюта расхода" value={e.currency} onChange={v => update(e.id, {currency: v.target.value.toUpperCase()})}/><TextField label="Фактический BYN-эквивалент (если известен)" type="number" value={e.actualByn ?? ""} onChange={v => update(e.id, {actualByn: v.target.value === "" ? null : Number(v.target.value)})}/><TextField type="date" label="Дата расхода" InputLabelProps={{shrink: true}} value={e.date} onChange={v => update(e.id, {date: v.target.value})}/><TextField label="Документ / основание расхода" value={e.document} onChange={v => update(e.id, {document: v.target.value})}/>
            <TextField select label="Распределение расхода" value={e.allocation} onChange={v => update(e.id, {allocation: Number(v.target.value)})}>{["По стоимости", "По количеству", "По массе", "По объёму", "Вручную"].map((label, i) => <MenuItem key={label} value={i}>{label}</MenuItem>)}</TextField>
            <TextField select label="Область расхода" value={e.receiptId || ""} onChange={v => update(e.id, {receiptId: v.target.value || null})}><MenuItem value="">Вся закупка</MenuItem>{receiptIds.map(id => <MenuItem key={id} value={id}>Поступление {id.slice(0, 8)}</MenuItem>)}</TextField></div>
            <FormControlLabel label="Включить в управленческую себестоимость" control={<Checkbox checked={e.includeInCost} onChange={(_, checked) => update(e.id, {includeInCost: checked})}/>}/>
            {e.allocation === 4 && <div className="cost-fields">{invoice.lines.map(line => <TextField key={line.id} type="number" label={`${line.name}: доля BYN`} value={e.manualShares?.find(s => s.lineId === line.id)?.amount ?? ""} onChange={v => update(e.id, {manualShares: [...(e.manualShares || []).filter(s => s.lineId !== line.id), {lineId: line.id, amount: Number(v.target.value)}]})}/>)}</div>}
            <Button color="error" onClick={() => setExpenses(rows => rows.filter(r => r.id !== e.id))}>Убрать расход из нового расчёта</Button></section>)}
        <Button onClick={() => setExpenses(rows => [...rows, {id: newRequestId(), name: "", amount: 0, currency: "BYN", actualByn: null, date: new Date().toISOString().slice(0, 10), document: "", includeInCost: true, allocation: 0, receiptId: null, manualShares: null, rate: null, byn: null}])}>Добавить расход</Button>
        <details><summary>Ручное распределение платежей по SKU</summary><p className="cost-note">По умолчанию платежи распределяются по суммам строк инвойса в валюте. Сумма ручных долей должна совпадать с BYN-затратами платежа.</p>{invoice.payments.filter(p => !p.voidReason).map(payment => {const row = allocations.find(a => a.paymentId === payment.id); return <section className="cost-line" key={payment.id}><FormControlLabel label={`${payment.reference}: задать ручные доли BYN`} control={<Checkbox checked={!!row} onChange={(_, checked) => setAllocations(rows => checked ? [...rows, {paymentId: payment.id, shares: [], reason: ""}] : rows.filter(a => a.paymentId !== payment.id))}/>}/>{row && <><div className="cost-fields">{invoice.lines.map(line => <TextField key={line.id} type="number" label={line.name} value={row.shares.find(s => s.lineId === line.id)?.amount ?? ""} onChange={v => setAllocations(rows => rows.map(a => a.paymentId === payment.id ? {...a, shares: [...a.shares.filter(s => s.lineId !== line.id), {lineId: line.id, amount: Number(v.target.value)}]} : a))}/>)}</div><TextField fullWidth label="Основание ручного распределения" value={row.reason} onChange={v => setAllocations(rows => rows.map(a => a.paymentId === payment.id ? {...a, reason: v.target.value} : a))}/></>}</section>;})}</details>
        <details><summary>Возвраты, скидки и исправления управленческой стоимости</summary>{adjustments.map(a => <section className="cost-line" key={a.id}><div className="cost-fields"><TextField select label="Строка корректировки" value={a.lineId} onChange={e => setAdjustments(rows => rows.map(r => r.id === a.id ? {...r, lineId: e.target.value} : r))}>{invoice.lines.map(l => <MenuItem key={l.id} value={l.id}>{l.name}</MenuItem>)}</TextField>{([['byn', 'Поправка BYN (+ / −)'], ['reason', 'Причина корректировки'], ['document', 'Документ корректировки'], ['date', 'Дата корректировки']] as const).map(([key, label]) => <TextField key={key} label={label} type={key === "byn" ? "number" : key === "date" ? "date" : "text"} InputLabelProps={{shrink: true}} value={a[key]} onChange={e => setAdjustments(rows => rows.map(r => r.id === a.id ? {...r, [key]: key === "byn" ? Number(e.target.value) : e.target.value} : r))}/>)}</div><Button color="error" onClick={() => setAdjustments(rows => rows.filter(r => r.id !== a.id))}>Убрать корректировку</Button></section>)}<Button onClick={() => setAdjustments(rows => [...rows, {id: newRequestId(), lineId: invoice.lines[0].id, byn: 0, reason: "", document: "", date: new Date().toISOString().slice(0,10)}])}>Добавить корректировку</Button><p className="cost-note">Это поправка управленческого расчёта. Физический возврат количества оформляется отдельно на складе.</p></details>
        <TextField sx={{mt: 2}} fullWidth required label="Общее основание изменения" value={reason} onChange={e => setReason(e.target.value)}/>
    </DialogContent><DialogActions><Button onClick={close}>Отмена</Button><Button variant="contained" disabled={state.isLoading || !reason.trim()} onClick={async () => {try {await save({id: invoice.id, stamp, valuationDate: valuationDate || null, expenses, paymentAllocations: allocations, adjustments, reason}).unwrap(); close();} catch (e) {setFailure(procurementError(e));}}}>Сохранить расходы и основание</Button></DialogActions></Dialog>;
}

function PurchaseDetail({id, access, close}: {id: string; access: PricingAccess; close: () => void}) {
    const {data: view, isLoading, error, isError, refetch} = useProcurementInvoiceQuery(id, {pollingInterval: 10000});
    const [calculate, calcState] = useCalculateProcurementMutation(); const [apply, applyState] = useApplyManagementCostMutation(); const [link, linkState] = useLinkProcurementReceiptMutation(); const [confirm, confirmState] = useConfirmPaymentValuationMutation();
    const [expenses, setExpenses] = useState(false); const [failure, setFailure] = useState(""); const [versionId, setVersionId] = useState(""); const [lineId, setLineId] = useState(""); const [calculationId, setCalculationId] = useState(""); const [reason, setReason] = useState("");
    const [valuation, setValuation] = useState({paymentId: "", byn: "", method: "Согласованный управленческий эквивалент", reason: ""});
    const line = view?.invoice.lines.find(l => l.id === lineId);
    const {data: loose} = useReceiptPricingQuery({productId: line?.productId, pageSize: 500}, {skip: !line || !access.canOverridePurchase});
    const latest = view?.versions[0]; const selected = view?.versions.find(v => v.id === versionId) || latest;
    const run = async (work: () => Promise<unknown>) => {setFailure(""); try {await work();} catch (e) {setFailure(procurementError(e));}};
    return <Dialog open onClose={close} maxWidth="lg" fullWidth><DialogTitle>{view?.invoice.title || "Управленческая закупочная стоимость"}</DialogTitle><DialogContent>
        {isLoading ? <p>Загрузка закупки…</p> : isError ? <QueryError error={error} onRetry={refetch}/> : view && <>
        {failure && <Alert severity="error">{failure}</Alert>}<div className="cost-header"><div><strong>{view.invoice.supplier} · {view.invoice.number} · {view.invoice.date}</strong><p>Исходная валюта: {view.invoice.currency}. Стоимость рассчитывается отдельно для каждого поступления.</p></div><Button component={Link} to={`/costing/purchases/${id}`}>Инвойс, оплаты и документы</Button></div>
        {view.invoice.rateError && <Alert severity="warning">Справочный курс инвойса: {view.invoice.rateError}</Alert>}
        {view.invoice.invoiceRate && <p className="cost-note">Справочный курс инвойса: {view.invoice.invoiceRate.scale} {view.invoice.currency} = {money(view.invoice.invoiceRate.officialRate)} BYN на {view.invoice.invoiceRate.effectiveDate}. Он не заменяет фактические затраты банка.</p>}
        <div className="cost-table-wrap"><table className="cost-table"><thead><tr><th>SKU</th><th>Заказано</th><th>Цена инвойса</th><th>Сумма инвойса</th></tr></thead><tbody>{view.invoice.lines.map(l => <tr key={l.id}><td>{l.name}<small>{l.gtin}</small></td><td>{l.quantity} {l.unit}<small>{l.baseQuantity} {l.baseUnit}</small></td><td>{money(l.unitPriceFx)} {view.invoice.currency}/{l.unit}</td><td>{money(l.amountFx)} {view.invoice.currency}</td></tr>)}</tbody></table></div>
        <h3>Платежи</h3>{view.invoice.payments.map(p => <section className="cost-line" key={p.id}><strong>{p.reference} · {p.date} · {money(p.amountFx)} {view.invoice.currency}</strong><p>Фактически списано: {money(p.actualByn)} BYN; курс банка: {money(p.bankRate)}.</p>{p.officialRate ? <p className="cost-note">НБРБ: {p.officialRate.scale} {p.officialRate.currency} = {money(p.officialRate.officialRate)} BYN на {p.officialRate.effectiveDate}</p> : <p className="cost-note">{p.rateError || "Курс даты платежа не получен"}</p>}{p.voidReason ? <Alert severity="warning">Аннулирован: {p.voidReason}</Alert> : p.actualByn == null && access.canEditCost && <Button onClick={() => setValuation(v => ({...v, paymentId: p.id}))}>Подтвердить внутренний BYN-эквивалент</Button>}{view.ledger.paymentValuations.filter(v => v.paymentId === p.id).map(v => <p key={v.paymentId}>Внутренний метод: {v.method}; {money(v.byn)} BYN; {v.confirmedBy}; основание: {v.reason}</p>)}</section>)}
        {valuation.paymentId && <section className="cost-line"><Alert severity="info">Используется для оплаты с валютного счёта, когда фактические затраты BYN не известны. Подтверждение сохраняет метод и автора.</Alert><div className="cost-fields"><TextField label="Управленческий эквивалент BYN" value={valuation.byn} onChange={e => setValuation(v => ({...v, byn: e.target.value}))}/><TextField label="Внутренний метод" value={valuation.method} onChange={e => setValuation(v => ({...v, method: e.target.value}))}/><TextField label="Основание эквивалента" value={valuation.reason} onChange={e => setValuation(v => ({...v, reason: e.target.value}))}/><Button disabled={confirmState.isLoading || !valuation.reason || !valuation.byn} onClick={() => run(async () => {await confirm({id, stamp: view.ledger.stamp, ...valuation, byn: valuation.byn.replace(",", ".")}).unwrap(); setValuation(v => ({...v, paymentId: ""}));})}>Подтвердить эквивалент</Button></div></section>}
        <div className="cost-actions">{access.canEditCost && <><Button onClick={() => setExpenses(true)}>Расходы и распределение</Button><Button variant="contained" disabled={calcState.isLoading} onClick={() => run(async () => {const result = await calculate(id).unwrap(); setVersionId(result.id);})}>Рассчитать новую версию</Button></>}<TextField size="small" select label="Версия управленческой стоимости" value={selected?.id || ""} onChange={e => setVersionId(e.target.value)} sx={{minWidth: 230}}>{view.versions.map(v => <MenuItem key={v.id} value={v.id}>Версия {v.version} · {new Date(v.createdAt).toLocaleString("ru-RU")}</MenuItem>)}</TextField></div>
        {selected && <><p>Оплачено {money(selected.result.paidFx)} из {money(selected.result.invoiceAmountFx)} {view.invoice.currency}; подтверждённые BYN-затраты: {money(selected.result.confirmedPaymentByn)}.</p>{selected.result.warnings.map(w => <Alert key={w} severity="warning">{w}</Alert>)}<div className="cost-table-wrap"><table className="cost-table"><thead><tr><th>Партия / товар</th><th>Закупка BYN/ед.</th><th>Расходы BYN</th><th>Себестоимость BYN/ед.</th><th>Статус / действие</th></tr></thead><tbody>{selected.result.receipts.map(r => {const c = view.receipts.find(c => c.receiptLineId === r.receiptLineId); return <tr key={r.receiptLineId}><td>{view.invoice.lines.find(l => l.id === r.invoiceLineId)?.name}<small>Приход {r.receiptId.slice(0, 8)} · {r.quantity} ед.</small></td><td>{money(r.unitPurchaseByn)}</td><td>{money(r.expensesByn)}</td><td>{money(r.unitCostByn)}</td><td><Chip size="small" color={r.isPreliminary ? "warning" : "success"} label={r.isPreliminary ? "Предварительно" : "Ожидает экономиста"}/><small>{r.method}</small>{r.warnings.map(w => <small key={w} className="pricing-warning">{w}</small>)}{access.canEditCost && c && <Button disabled={applyState.isLoading || r.unitCostByn == null || c.status === 4 || c.status === 5} onClick={() => run(async () => {await apply({versionId: selected.id, calculationId: c.id, stamp: c.stamp}).unwrap();})}>Перенести в черновик экономиста</Button>}<Button component={Link} to={`/costing?mode=receipts&productId=${r.productId}`}>Подтверждение и цена</Button></td></tr>;})}</tbody></table></div>{!selected.result.receipts.length && <Alert severity="info">Инвойс сохранён. После проведённой приёмки здесь появится стоимость каждой партии.</Alert>}<details><summary>Зафиксированные курсы даты оценки</summary>{selected.input.valuationRates.map(r => <p key={r.date}>{r.date}: {r.rate ? `${r.rate.scale} ${r.rate.currency} = ${money(r.rate.officialRate)} BYN; ${r.rate.source}` : r.error}</p>)}</details></>}
        {access.canOverridePurchase && <details><summary>Привязать дополнительное проведённое поступление</summary><p className="cost-note">Для частичной поставки выберите фактически проведённую строку прихода. Количество и остаток этим действием не изменяются.</p><div className="cost-fields"><TextField select label="Строка инвойса для привязки" value={lineId} onChange={e => {setLineId(e.target.value); setCalculationId("");}}>{view.invoice.lines.map(l => <MenuItem key={l.id} value={l.id}>{l.name}</MenuItem>)}</TextField><TextField select label="Проведённая строка прихода" value={calculationId} onChange={e => setCalculationId(e.target.value)}>{loose?.items.filter(r => !r.calculation.purchaseId && r.calculation.status < 4).map(r => <MenuItem key={r.calculation.id} value={r.calculation.id}>{r.calculation.productName} · {r.calculation.acceptedQuantity} {r.calculation.purchase.baseUnit} · {r.calculation.receiptId.slice(0, 8)}</MenuItem>)}</TextField><TextField label="Основание привязки" value={reason} onChange={e => setReason(e.target.value)}/><Button disabled={linkState.isLoading || !calculationId || !reason} onClick={() => run(async () => {const c = loose?.items.find(r => r.calculation.id === calculationId)?.calculation; if (c) await link({id, calculationId, lineId, stamp: c.stamp, reason}).unwrap();})}>Привязать партию</Button></div></details>}
        <details><summary>Журнал изменений расходов и управленческих методов</summary>{view.ledger.events.map((e, i) => <p key={i}>{new Date(e.at).toLocaleString("ru-RU")} · {e.actor} · {e.action}<br/><small style={{overflowWrap: "anywhere"}}>{e.note}</small></p>)}</details>
        {expenses && <ExpenseEditor view={view} close={() => setExpenses(false)}/>}</>}
    </DialogContent><DialogActions><Button onClick={close}>Закрыть</Button></DialogActions></Dialog>;
}

function Workspace({access}: {access: PricingAccess}) {
    const [params, setParams] = useSearchParams(); const [query, setQuery] = useState(""); const search = useDebounce(query); const [page, setPage] = useState(1); const [tab, setTab] = useState(params.get("purchaseId") ? 1 : 0);
    const catalog = useProcurementCatalogQuery({search, page}, {pollingInterval: 10000}); const purchases = useProcurementInvoicesQuery(undefined, {pollingInterval: 10000});
    const [skuId, setSkuId] = useState(0);
    const [purchaseId, setPurchaseId] = useState(params.get("purchaseId") || ""); const [supplier, setSupplier] = useState(""); const [currency, setCurrency] = useState("");
    useEffect(() => {if (params.get("purchaseId")) setPurchaseId(params.get("purchaseId")!);}, [params]);
    const list = purchases.data?.filter(i => (!supplier || i.supplier.toLocaleLowerCase().includes(supplier.toLocaleLowerCase())) && (!currency || i.currency === currency) && (!search || `${i.title} ${i.number} ${i.lines.map(l => `${l.name} ${l.gtin}`).join(" ")}`.toLocaleLowerCase().includes(search.toLocaleLowerCase())));
    const open = (id: string) => {setSkuId(0); setPurchaseId(id); setParams(p => {p.set("purchaseId", id); return p;});};
    return <div className="cost-page"><header className="cost-header"><div><span className="cost-eyebrow">Управленческий расчёт в BYN</span><h1>Валютные закупки и себестоимость</h1><p>Каталог виден до первой закупки. Стоимость каждой партии рассчитывается по оплатам и расходам; курс CMR не переоценивает оплаченную закупку.</p></div><div className="cost-actions">{access.canManagePurchases && <Button component={Link} to="/costing/purchases">Инвойсы и оплаты</Button>}<Button component={Link} to="/costing?mode=receipts">Права и утверждение цен</Button></div></header>
        <Tabs value={tab} onChange={(_, value) => setTab(value)}><Tab label="Все SKU"/><Tab label="Закупки и партии"/></Tabs><div className="cost-fields"><TextField label="Поиск SKU / GTIN / инвойса" value={query} onChange={e => {setQuery(e.target.value); setPage(1);}}/>{tab === 1 && <><TextField label="Поставщик закупки" value={supplier} onChange={e => setSupplier(e.target.value)}/><TextField label="Валюта закупки" value={currency} onChange={e => setCurrency(e.target.value.toUpperCase())}/></>}</div>
        <section className="cost-panel">{tab === 0 ? catalog.isError ? <QueryError error={catalog.error} onRetry={catalog.refetch}/> : <>
            <p className="cost-note">Стоимость последней принятой партии, за базовую единицу. До приёмки цена инвойса справочная. Отпускная цена — действующая утверждённая, без НДС.</p>
            <div className="cost-table-wrap"><table className="cost-table"><thead><tr><th>Товар / SKU</th><th>Закупочная цена, BYN</th><th>Себестоимость, BYN</th><th>Наценка, %</th><th>Отпускная цена, BYN</th><th>Этапы</th></tr></thead><tbody>{catalog.data?.items.map(row => <tr key={row.sku.id}>
                <td><Button onClick={() => setSkuId(row.sku.id)}>{row.sku.name}</Button><small>{row.sku.gtin || `SKU #${row.sku.id}`} · {row.sku.baseUnit || "ед."}</small><small>{row.summary.source}</small><small>Закупок: {row.purchases}</small></td>
                <td>{money(row.summary.purchaseByn)}{row.summary.isPreliminary && <small>Предварительно</small>}</td>
                <td>{money(row.summary.costByn)}{row.summary.calculatedAt && <small>{new Date(row.summary.calculatedAt).toLocaleDateString("ru-RU")}</small>}</td>
                <td>{money(row.summary.markupPercent)}</td><td>{row.summary.sellingPriceByn == null ? "Не утверждена" : `${money(row.summary.sellingPriceByn)} BYN`}<small>Меняется после утверждения</small></td>
                <td><Chip size="small" label={row.status}/><small>{row.paymentStatus}</small><small>{row.receiptStatus}</small></td>
            </tr>)}</tbody></table></div>{catalog.isLoading && <p>Загрузка каталога…</p>}{!catalog.isLoading && !catalog.data?.items.length && <p>Товары не найдены.</p>}<Pagination page={page} count={Math.max(1, Math.ceil((catalog.data?.total || 0) / 30))} onChange={(_, value) => setPage(value)}/>
            </> : purchases.isError ? <QueryError error={purchases.error} onRetry={purchases.refetch}/> : <div className="cost-table-wrap"><table className="cost-table"><thead><tr><th>Закупка</th><th>Поставщик</th><th>Инвойс</th><th>Валюта</th><th/></tr></thead><tbody>{list?.map(i => <tr key={i.id}><td>{i.title}</td><td>{i.supplier}</td><td>{i.number} · {i.date}</td><td>{i.currency}</td><td><Button onClick={() => open(i.id)}>Открыть стоимость партий</Button></td></tr>)}</tbody></table>{!list?.length && <p>Сохраните инвойс в карточке поставки. Новые SKU уже доступны на вкладке «Все SKU».</p>}</div>}</section>
        {skuId > 0 && <ProcurementSkuDetail id={skuId} close={() => setSkuId(0)} openPurchase={open}/>}
        <RatePanel canOverride={access.canOverridePurchase}/>{purchaseId && <PurchaseDetail id={purchaseId} access={access} close={() => {setPurchaseId(""); setParams(p => {p.delete("purchaseId"); return p;});}}/>}</div>;
}
function WarehouseCatalog() {
    const [search, setSearch] = useState(""); const [page, setPage] = useState(1); const debounced = useDebounce(search, 300);
    const query = useProcurementCatalogStagesQuery({search: debounced, page});
    return <><section className="cost-panel"><h1>Товары и этапы закупки</h1><TextField label="Поиск SKU / GTIN" value={search} onChange={e => {setSearch(e.target.value); setPage(1);}}/>
        {query.isError ? <QueryError error={query.error} onRetry={query.refetch}/> : query.isLoading ? <p>Загрузка товаров…</p> : <><table className="cost-table"><thead><tr><th>Товар</th><th>GTIN</th><th>Базовая единица</th><th>Этап</th></tr></thead><tbody>{query.data?.items.map(s => <tr key={s.id}><td>{s.name}</td><td>{s.gtin}</td><td>{s.baseUnit}</td><td>{s.status}</td></tr>)}</tbody></table><Pagination page={page} count={Math.max(1, Math.ceil((query.data?.total || 0) / 30))} onChange={(_, p) => setPage(p)}/></>}
        </section><ReceiptPricingPage/></>;
}
export default function ProcurementCostingPage() {
    const policy = useReceiptPricingPolicyQuery(); const a = policy.data?.access;
    if (policy.isError) return <QueryError error={policy.error} onRetry={policy.refetch}/>;
    if (!a) return <p>Загрузка прав…</p>;
    return a.canEditCost || a.canSetMarkup || a.canApprove || a.canOverridePurchase || a.canManagePolicy || a.canManagePurchases ? <Workspace access={a}/> : <WarehouseCatalog/>;
}
